import Foundation

/// Token-free request context generated by sign-in or restored from credential storage.
/// Data properties use JSON's Base64 encoding.
struct RitualDeviceContext: Codable, Equatable, Sendable {

    private enum CodingKeys: String, CodingKey {
        case clientContext, capabilities, userAgent
    }

    /// Payload of common protobuf field 2, including the device, user, locale and location.
    let clientContext: Data
    /// Payload of common protobuf field 157, preserving unknown capability flags.
    let capabilities: Data
    /// Ritual client user agent for this context.
    let userAgent: String

    /// Creates and validates context without reading a capture or contacting Ritual.
    init(clientContext: Data, capabilities: Data, userAgent: String) throws {
        self.clientContext = clientContext
        self.capabilities = capabilities
        self.userAgent = userAgent
        try validate()
    }

    init(from decoder: Decoder) throws {
        let values = try decoder.container(keyedBy: CodingKeys.self)
        clientContext = try values.decode(Data.self, forKey: .clientContext)
        capabilities = try values.decode(Data.self, forKey: .capabilities)
        userAgent = try values.decode(String.self, forKey: .userAgent)
        try validate()
    }

    /// Restores saved or externally supplied JSON
    static func parse(_ json: String) throws -> Self {
        do {
            return try JSONDecoder().decode(Self.self, from: Data(json.utf8))
        } catch {
            throw RitualDownloadError.invalidContext(
                "Expected clientContext and capabilities as Base64, plus userAgent; context must include device, user and location."
            )
        }
    }

    private func validate() throws {
        guard clientContext.count <= 1_048_576, capabilities.count <= 1_048_576, !userAgent.isEmpty, !userAgent.contains("\n"), !userAgent.contains("\r") else {
            throw RitualDownloadError.invalidContext("Missing or oversized context, or invalid user agent")
        }
        let context = try ProtoMessage(clientContext)
        guard context.string(1)?.isEmpty == false, context.string(4)?.isEmpty == false, context.bytes(8) != nil, !capabilities.isEmpty else {
            throw RitualDownloadError.invalidContext("Missing device UUID, user ID, location or capabilities")
        }
        _ = try ProtoMessage(capabilities)
    }

}
